/**
 * GHOSTLINK SERVER v2 — Production-Ready LAN Relay
 *
 * Changes vs v1:
 *  - Interface selector: lists all real non-virtual adapters; auto-picks
 *    Wi-Fi or lets user set GHOSTLINK_IP env var. Virtual adapters
 *    (VMware/Hyper-V/VirtualBox/WSL/Bluetooth) are excluded by default.
 *  - mkcert-aware: uses existing cert.pem/key.pem (generated by mkcert)
 *    rather than self-generating a selfsigned cert. Falls back to selfsigned
 *    only if cert files are absent.
 *  - Startup QR: prints an ASCII QR of the HTTPS URL to the terminal so
 *    phones can scan directly without reading the IP manually.
 *  - Share link registry: /api/join?id=XXXX&pk=PUBKEYHEX —
 *    carries only the public invite ID and host public key, NEVER the secret.
 *  - Typed-code join flow: When the scanner uses only the typed code (no QR
 *    secret), the server delivers the host pubkey so both sides can compute
 *    an ephemeral DH session. The client still cannot derive the AEAD keys
 *    until safety-number comparison succeeds (enforced client-side).
 *  - Windows Firewall note printed at startup.
 *  - SECURITY: Server stores ZERO message content, ZERO secrets.
 */

const http    = require('http');
const https   = require('https');
const fs      = require('fs');
const path    = require('path');
const os      = require('os');
const crypto  = require('crypto');
const readline = require('readline');
const { WebSocketServer, WebSocket } = require('ws');
const QRCode  = require('qrcode');
const Invitation = require('./js/invitation');

const HTTP_PORT         = 8088;
const HTTPS_PORT        = 8443;
const INVITATION_TTL_MS = 5 * 60 * 1000;   // 5 minutes
const MAX_PAIR_ATTEMPTS = 5;

// ── Adapter classification ────────────────────────────────────────────────────
// These prefix/name patterns identify virtual and non-routable adapters that
// should NOT be used for phone-to-PC communication.
const VIRTUAL_PATTERNS = [
  /vmware/i, /vmnet/i, /vboxnet/i, /virtualbox/i,
  /hyper-v/i, /vethernet/i, /wsl/i, /loopback/i,
  /bluetooth/i, /teredo/i, /isatap/i, /tunnel/i,
  /pseudo/i, /6to4/i, /local area connection\* /i,
];

function classifyInterfaces() {
  const nets = os.networkInterfaces();
  const real = [];
  const virtual_ = [];

  for (const [name, addrs] of Object.entries(nets)) {
    for (const addr of addrs) {
      if (addr.family !== 'IPv4') continue;
      if (addr.internal) continue;
      // 169.254.x.x = link-local (APIPA), not routable
      if (addr.address.startsWith('169.254.')) continue;

      const isVirtual = VIRTUAL_PATTERNS.some(p => p.test(name));
      const entry = { name, address: addr.address, mac: addr.mac };
      isVirtual ? virtual_.push(entry) : real.push(entry);
    }
  }
  return { real, virtual_ };
}

function pickInterface(real) {
  // Prefer Wi-Fi / WLAN / Wireless interfaces
  const wifi = real.find(i =>
    /wi-fi|wlan|wireless|802\.11/i.test(i.name)
  );
  if (wifi) return wifi;
  // Then Ethernet
  const eth = real.find(i => /ethernet|eth|en[0-9]/i.test(i.name));
  if (eth) return eth;
  // Fallback: first real adapter
  return real[0] || null;
}

async function chooseInterface(real) {
  const forcedIp = process.env.GHOSTLINK_IP;
  if (forcedIp) {
    const forced = real.find(i => i.address === forcedIp);
    if (forced) return forced;
    console.warn(`[WARN] GHOSTLINK_IP=${forcedIp} is not an eligible physical adapter.`);
  }
  if (!process.stdin.isTTY || real.length === 1) return pickInterface(real);
  const defaultChoice = real.indexOf(pickInterface(real));
  const rl = readline.createInterface({ input: process.stdin, output: process.stdout });
  const answer = await new Promise(resolve => rl.question(`Select adapter [${defaultChoice}]: `, resolve));
  rl.close();
  const index = answer.trim() === '' ? defaultChoice : Number(answer);
  if (!Number.isInteger(index) || !real[index]) throw new Error('Invalid adapter selection.');
  return real[index];
}

// ── Certificate loading ───────────────────────────────────────────────────────
const certPath = path.join(__dirname, 'cert.pem');
const keyPath  = path.join(__dirname, 'key.pem');

function getSslOptions(lanIp) {
  if (fs.existsSync(certPath) && fs.existsSync(keyPath)) {
    const cert = fs.readFileSync(certPath);
    const key = fs.readFileSync(keyPath);
    const certificate = new crypto.X509Certificate(cert);
    if (!certificate.checkIP(lanIp)) {
      throw new Error(`cert.pem does not include ${lanIp} in its subject alternative names. Run: mkcert -cert-file cert.pem -key-file key.pem ${lanIp} localhost 127.0.0.1`);
    }
    if (new Date(certificate.validFrom) > new Date() || new Date(certificate.validTo) <= new Date()) {
      throw new Error('cert.pem is not currently valid. Regenerate it with mkcert.');
    }
    if (!crypto.createPublicKey(key).export({ type: 'spki', format: 'der' }).equals(
      crypto.createPublicKey(cert).export({ type: 'spki', format: 'der' }))) {
      throw new Error('cert.pem and key.pem do not match. Regenerate both with mkcert.');
    }
    console.log(`[TLS] Using cert.pem/key.pem for ${lanIp}:${HTTPS_PORT}; SAN: ${certificate.subjectAltName}.`);
    return {
      cert,
      key,
    };
  }
  throw new Error(`mkcert certificate missing. Run: mkcert -cert-file cert.pem -key-file key.pem ${lanIp} localhost 127.0.0.1`);
}

// ── MIME types ────────────────────────────────────────────────────────────────
const MIME = {
  '.html': 'text/html', '.css': 'text/css', '.js': 'text/javascript',
  '.json': 'application/json', '.png': 'image/png', '.jpg': 'image/jpeg',
  '.svg': 'image/svg+xml', '.ico': 'image/x-icon', '.wasm': 'application/wasm',
};

// ── In-Memory State ───────────────────────────────────────────────────────────
// clients:     Map<clientId, { ws, id, alias, pairedWith, pubKeyHex, clientPubKeyHex }>
// invitations: Map<code, { hostId, hostPubKeyHex, exp, attempts, inviteId }>
const clients     = new Map();
const invitations = new Map();  // keyed by 8-char XXXX-XXXX code
const inviteIndex = new Map();  // keyed by short inviteId for link flow

setInterval(() => {
  const now = Date.now();
  for (const [code, inv] of invitations.entries()) {
    if (now > inv.exp) {
      inviteIndex.delete(inv.inviteId);
      invitations.delete(code);
    }
  }
}, 10_000);

// ── HTTP request handler ──────────────────────────────────────────────────────
let LOCAL_IP = '127.0.0.1';   // updated once we know the chosen adapter

function handleHttpRequest(req, res) {
  const urlObj  = new URL(req.url, `https://${req.headers.host || LOCAL_IP}`);
  const pathname = urlObj.pathname;

  // CORS for same-origin API calls
  res.setHeader('Access-Control-Allow-Origin', '*');

  // ── API: Generate ISO/IEC 18004 QR SVG ──────────────────────────────────
  if (pathname === '/api/qr') {
    const text = urlObj.searchParams.get('text');
    if (!text || text.length > 4096) { res.writeHead(400); res.end('Invalid QR payload'); return; }
    QRCode.toString(text, {
      type: 'svg', margin: 4, errorCorrectionLevel: 'M',
      color: { dark: '#000000', light: '#FFFFFF' },
    }, (err, svg) => {
      if (err) { res.writeHead(500); res.end('QR error'); return; }
      res.writeHead(200, { 'Content-Type': 'image/svg+xml', 'Cache-Control': 'no-store' });
      res.end(svg);
    });
    return;
  }

  // ── API: Live peer list ──────────────────────────────────────────────────
  if (pathname === '/api/peers') {
    const peers = [];
    clients.forEach(c => peers.push({ id: c.id, alias: c.alias, isPaired: !!c.pairedWith }));
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ peers, lanIp: LOCAL_IP, httpsPort: HTTPS_PORT, httpPort: HTTP_PORT }));
    return;
  }

  // ── API: Lookup invitation by inviteId (link join flow) ──────────────────
  // Returns ONLY the host's pubkey and alias. Secret never stored here.
  if (pathname === '/api/join') {
    const inviteId = urlObj.searchParams.get('id');
    const inv = inviteIndex.get(inviteId);
    if (!inv || Date.now() > inv.exp || !clients.has(inv.hostId)) {
      res.writeHead(404, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Invitation not found or expired' }));
      return;
    }
    const host = clients.get(inv.hostId);
    res.writeHead(200, { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' });
    res.end(JSON.stringify({
      hostAlias:     host ? host.alias : 'Ghost',
      exp:           inv.exp,
    }));
    return;
  }

  // ── API: Server info (for the startup QR / client) ───────────────────────
  if (pathname === '/api/info') {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ lanIp: LOCAL_IP, httpsPort: HTTPS_PORT }));
    return;
  }

  // ── Static file serving ──────────────────────────────────────────────────
  let filePath = path.join(__dirname, pathname === '/' ? 'index.html' : pathname);
  const ext    = path.extname(filePath).toLowerCase();
  const ctype  = MIME[ext] || 'application/octet-stream';

  fs.readFile(filePath, (err, content) => {
    if (err) {
      res.writeHead(err.code === 'ENOENT' ? 404 : 500);
      res.end(err.code === 'ENOENT' ? '404 Not Found' : `Server Error: ${err.code}`);
      return;
    }
    // No-cache for HTML so phones always get the latest app.
    // IMPORTANT: Clear-Site-Data must ONLY be sent on the HTML document.
    // Sending it on every JS/CSS response made Chromium wipe storage mid-load
    // and abort script execution, leaving the app inert (QR never rendered).
    const headers = {
      'Content-Type': ctype,
      'Cache-Control': 'no-store, no-cache, must-revalidate',
    };
    if (ext === '.html' || pathname === '/') {
      headers['Clear-Site-Data'] = '"cache", "storage"';
    }
    res.writeHead(200, headers);
    res.end(content);
  });
}

// ── WebSocket helpers ─────────────────────────────────────────────────────────
function broadcastPeerList() {
  const peers = [];
  clients.forEach(c => peers.push({ id: c.id, alias: c.alias, isPaired: !!c.pairedWith }));
  const msg = JSON.stringify({ type: 'peer_list', peers });
  clients.forEach(c => { if (c.ws.readyState === WebSocket.OPEN) c.ws.send(msg); });
}

function sendTo(clientId, obj) {
  const c = clients.get(clientId);
  if (c && c.ws.readyState === WebSocket.OPEN) { c.ws.send(JSON.stringify(obj)); return true; }
  return false;
}

// ── WebSocket connection handler ──────────────────────────────────────────────
function handleWsConnection(ws) {
  const clientId = 'peer_' + Math.random().toString(36).substring(2, 9);
  const clientData = {
    ws, id: clientId, pairedWith: null, lastSeen: Date.now(),
    alias: 'Shadow_' + clientId.substring(5).toUpperCase(),
    pubKeyHex: null, clientPubKeyHex: null,
  };
  clients.set(clientId, clientData);

  ws.send(JSON.stringify({
    type: 'welcome', clientId, assignedAlias: clientData.alias,
    lanIp: LOCAL_IP, port: HTTPS_PORT,
  }));
  broadcastPeerList();

  ws.on('message', rawMsg => {
    try {
      const msg = JSON.parse(rawMsg.toString());
      clientData.lastSeen = Date.now();

      switch (msg.type) {

        // ── Ephemeral presence (alias + pubkey refresh) ──────────────────────
        case 'presence':
          if (msg.alias)    clientData.alias      = msg.alias;
          if (msg.pubKeyHex) clientData.pubKeyHex = msg.pubKeyHex;
          broadcastPeerList();
          break;

        // ── Register single-use 5-minute invitation ──────────────────────────
        case 'register_invitation': {
          const code = Invitation.normalize(msg.code);
          if (!code || !msg.hostPubKeyHex) {
            ws.send(JSON.stringify({ type: 'pair_error', error: 'Invitation code must contain exactly eight letters or numbers.' }));
            break;
          }
          if (!/^[0-9a-f]{64}$/i.test(msg.hostPubKeyHex)) {
            ws.send(JSON.stringify({ type: 'pair_error', error: 'Invalid host public key.' }));
            break;
          }
          // Short random inviteId for the https share link (carries no secret)
          const inviteId = crypto.randomBytes(16).toString('base64url');
          const inv = {
            hostId:       clientId,
            hostPubKeyHex: msg.hostPubKeyHex,
            code,
            inviteId,
            exp:      Date.now() + INVITATION_TTL_MS,
            attempts: 0,
          };
          const previous = invitations.get(code);
          if (previous && previous.hostId !== clientId && Date.now() <= previous.exp) {
            ws.send(JSON.stringify({ type: 'pair_error', error: 'Invitation code already in use. Generate another.' }));
            break;
          }
          if (previous) inviteIndex.delete(previous.inviteId);
          for (const [oldCode, old] of invitations) {
            if (old.hostId === clientId) { invitations.delete(oldCode); inviteIndex.delete(old.inviteId); }
          }
          invitations.set(code, inv);
          inviteIndex.set(inviteId, inv);
          clientData.pubKeyHex = msg.hostPubKeyHex;
          // Return the inviteId so the client can build the share link
          ws.send(JSON.stringify({ type: 'invitation_registered', code, inviteId }));
          break;
        }

        // ── Scanner requests pairing via code ────────────────────────────────
        case 'request_pair': {
          const code = Invitation.normalize(msg.code);
          if (!code) {
            ws.send(JSON.stringify({ type: 'pair_error', error: 'Invitation code must contain exactly eight letters or numbers.' }));
            break;
          }
          if (!/^[0-9a-f]{64}$/i.test(msg.clientPubKeyHex)) {
            ws.send(JSON.stringify({ type: 'pair_error', error: 'Invalid client public key.' }));
            break;
          }
          const inv  = invitations.get(code);

          if (!inv) {
            ws.send(JSON.stringify({ type: 'pair_error', error: 'Invitation code not found or already expired.' }));
            break;
          }
          if (Date.now() > inv.exp) {
            invitations.delete(code); inviteIndex.delete(inv.inviteId);
            ws.send(JSON.stringify({ type: 'pair_error', error: 'Invitation has expired (5-minute limit).' }));
            break;
          }
          inv.attempts++;
          if (inv.attempts > MAX_PAIR_ATTEMPTS) {
            invitations.delete(code); inviteIndex.delete(inv.inviteId);
            ws.send(JSON.stringify({ type: 'pair_error', error: 'Maximum attempts exceeded. Invitation code destroyed.' }));
            break;
          }
          const hostClient = clients.get(inv.hostId);
          if (!hostClient || hostClient.ws.readyState !== WebSocket.OPEN || hostClient.id === clientId) {
            ws.send(JSON.stringify({ type: 'pair_error', error: 'Cannot pair with yourself or host is offline.' }));
            break;
          }
          // Save scanner's pubkey
          clientData.clientPubKeyHex = msg.clientPubKeyHex;
          // Mark as typed-code join if no QR secret was presented
          const isTypedCodeJoin = !!msg.typedCodeOnly;

          // Inform scanner: host found
          ws.send(JSON.stringify({
            type: 'pair_matched', hostId: hostClient.id, hostAlias: hostClient.alias,
            hostPubKeyHex: inv.hostPubKeyHex, code, isTypedCodeJoin,
          }));
          // Inform host: incoming request
          sendTo(hostClient.id, {
            type: 'incoming_pair_request', fromId: clientId, fromAlias: clientData.alias,
            clientPubKeyHex: msg.clientPubKeyHex, code, isTypedCodeJoin,
          });
          break;
        }

        // ── Host accepts pairing ─────────────────────────────────────────────
        case 'accept_pair': {
          const peer = clients.get(msg.peerId);
          if (!peer) break;

          clientData.pairedWith = msg.peerId;
          peer.pairedWith = clientId;

          // Invalidate invitation
          for (const [code, inv] of invitations.entries()) {
            if (inv.hostId === clientId) {
              inviteIndex.delete(inv.inviteId);
              invitations.delete(code);
            }
          }

          const isTypedCodeJoin = !!msg.isTypedCodeJoin;
          // Host -> gets scanner's pubkey
          ws.send(JSON.stringify({
            type: 'pair_connected', peerId: peer.id, peerAlias: peer.alias,
            peerPubKeyHex: peer.clientPubKeyHex || msg.peerPubKeyHex,
            isHost: true, isTypedCodeJoin,
          }));
          // Scanner -> gets host's pubkey
          sendTo(peer.id, {
            type: 'pair_connected', peerId: clientId, peerAlias: clientData.alias,
            peerPubKeyHex: clientData.pubKeyHex || msg.hostPubKeyHex,
            isHost: false, isTypedCodeJoin,
          });
          broadcastPeerList();
          break;
        }

        // ── Host rejects ─────────────────────────────────────────────────────
        case 'reject_pair':
          sendTo(msg.peerId, { type: 'pair_rejected', fromAlias: clientData.alias });
          break;

        // ── Blind relay of AEAD ciphertext (server never sees plaintext) ─────
        case 'encrypted_blob': {
          if (!clientData.pairedWith) break;
          // Hard-limit: 2 KB ciphertext hex = 4096 hex chars
          if (!msg.ciphertextHex || msg.ciphertextHex.length > 4096) break;
          sendTo(clientData.pairedWith, {
            type: 'encrypted_blob', fromId: clientId,
            counter: msg.counter, nonceHex: msg.nonceHex,
            ciphertextHex: msg.ciphertextHex, timestamp: msg.timestamp || Date.now(),
          });
          break;
        }

        // ── Session termination / panic ──────────────────────────────────────
        case 'terminate_session': {
          if (clientData.pairedWith) {
            sendTo(clientData.pairedWith, { type: 'session_terminated', reason: msg.reason || 'exit' });
            const peer = clients.get(clientData.pairedWith);
            if (peer) peer.pairedWith = null;
            clientData.pairedWith = null;
          }
          broadcastPeerList();
          break;
        }
      }
    } catch (e) {
      console.error('[WS Message Error]', e.message);
    }
  });

  ws.on('close', () => {
    if (clientData.pairedWith) {
      sendTo(clientData.pairedWith, { type: 'session_terminated', reason: 'peer_disconnected' });
      const peer = clients.get(clientData.pairedWith);
      if (peer) peer.pairedWith = null;
    }
    // Clean up invitations
    for (const [code, inv] of invitations.entries()) {
      if (inv.hostId === clientId) { inviteIndex.delete(inv.inviteId); invitations.delete(code); }
    }
    clients.delete(clientId);
    broadcastPeerList();
  });
}

// ── ASCII QR printer ──────────────────────────────────────────────────────────
async function printStartupQr(url) {
  try {
    const ascii = await QRCode.toString(url, { type: 'terminal', small: true });
    console.log('\n' + ascii);
    console.log(`  Scan above to open GhostLink on your phone.\n`);
  } catch (e) {
    console.log(`  Open on phone: ${url}\n`);
  }
}

// ── Main startup ──────────────────────────────────────────────────────────────
async function start() {
  // 1. Detect adapters
  const { real, virtual_ } = process.env.GHOSTLINK_TEST === '1'
    ? { real: [{ name: 'Test loopback', address: '127.0.0.1', mac: '00:00:00:00:00:00' }], virtual_: [] }
    : classifyInterfaces();

  console.log('\n============================================================');
  console.log('  GHOSTLINK SERVER v2 — Network Interface Detection');
  console.log('============================================================');

  if (real.length === 0) {
    console.error('[ERROR] No routable network interfaces found. Is Wi-Fi connected?');
    process.exit(1);
  }

  console.log('\n  Real (routable) adapters:');
  real.forEach((i, idx) => console.log(`    [${idx}] ${i.name.padEnd(30)} ${i.address}`));

  if (virtual_.length > 0) {
    console.log('\n  Virtual / excluded adapters (not used for phones):');
    virtual_.forEach(i => console.log(`    ✗  ${i.name.padEnd(30)} ${i.address}`));
  }

  // 2. Always offer a physical adapter selection in an interactive terminal.
  const chosen = await chooseInterface(real);

  if (!chosen) {
    console.error('[ERROR] Could not select a network adapter.');
    process.exit(1);
  }

  LOCAL_IP = chosen.address;

  // 3. TLS certificates
  let sslOptions;
  try {
    sslOptions = getSslOptions(LOCAL_IP);
  } catch (e) {
    console.error('[TLS] Failed to load certificates:', e.message);
    process.exit(1);
  }

  // 4. Wire up HTTP + WebSocket servers
  const httpServer  = http.createServer(handleHttpRequest);
  const httpsServer = https.createServer(sslOptions, handleHttpRequest);

  const wssHttp  = new WebSocketServer({ server: httpServer });
  const wssHttps = new WebSocketServer({ server: httpsServer });

  wssHttp.on('connection',  handleWsConnection);
  wssHttps.on('connection', handleWsConnection);

  // 5. Start mDNS if available
  try {
    const { Bonjour } = require('bonjour-service');
    const bonjour = new Bonjour();
    bonjour.publish({ name: 'GhostLink-P2P', type: 'ghostlink', port: HTTPS_PORT, txt: { v: '2', ssl: 'true', ip: LOCAL_IP } });
    console.log('\n[mDNS] GhostLink-P2P broadcast active on local subnet.');
  } catch (e) {
    console.warn('[mDNS] Bonjour unavailable:', e.message);
  }

  // 6. Listen on ALL interfaces so localhost, 127.0.0.1 and the LAN IP all work.
  //    (Binding only to LOCAL_IP previously broke http://localhost:8088/.)
  const BIND_ADDR = process.env.GHOSTLINK_BIND || '0.0.0.0';
  await new Promise(r => httpServer.listen(HTTP_PORT, BIND_ADDR, r));
  await new Promise(r => httpsServer.listen(HTTPS_PORT, BIND_ADDR, r));

  const httpsUrl = `https://${LOCAL_IP}:${HTTPS_PORT}`;
  const localHttpUrl = `http://localhost:${HTTP_PORT}`;

  console.log('\n============================================================');
  console.log('  GHOSTLINK SECURE P2P LAN SERVER ACTIVE');
  console.log('============================================================');
  console.log(`  Chosen adapter: ${chosen.name}`);
  console.log(`  LAN IP:         ${LOCAL_IP}`);
  console.log(`  HTTPS (Phones): ${httpsUrl}`);
  console.log(`  HTTP (Local):   ${localHttpUrl}`);
  console.log(`  HTTP (LAN):     http://${LOCAL_IP}:${HTTP_PORT}`);
  console.log(`  Protocol:       Libsodium X25519 + XChaCha20-Poly1305 AEAD`);
  console.log('');
  console.log('  ⚠ WINDOWS FIREWALL: To allow phones on your hotspot to reach');
  console.log(`  this server, run once in an ADMIN PowerShell:`);
  console.log('');
  console.log(`  New-NetFirewallRule -DisplayName "GhostLink HTTPS" \`
    -Direction Inbound -Protocol TCP \`
    -LocalPort ${HTTPS_PORT} -Action Allow`);
  console.log('');
  console.log(`  New-NetFirewallRule -DisplayName "GhostLink HTTP" \`
    -Direction Inbound -Protocol TCP \`
    -LocalPort ${HTTP_PORT} -Action Allow`);
  console.log('============================================================');

  await printStartupQr(httpsUrl);

  // Override to pick a different adapter: GHOSTLINK_IP=<IP> node server.js
  if (real.length > 1) {
    console.log(`  Tip: to force a different adapter:`);
    real.forEach(i => console.log(`    GHOSTLINK_IP=${i.address} node server.js`));
    console.log('');
  }
}

start().catch(err => {
  console.error('[Fatal] Server failed to start:', err);
  process.exit(1);
});
